t=np.arange(0,48);base=70+8*np.sin(2*np.pi*t/24);gbm=base+4*np.sin(t/5);jump=base+4*np.sin(t/5);jump[27:31]+=np.array([80,180,95,35]);ax.plot(t,gbm,color=ACCENT,lw=2,label='continuous baseline');ax.plot(t,jump,color=BAD,lw=2,label='with scarcity jump');ax.axhline(70,color=MUTED,lw=1,ls=(0,(4,3)));ax.set_xlabel('Hour');ax.set_ylabel('Power price (USD/MWh)');ax.set_title('A spike dominates short-horizon risk',loc='left');ax.legend(fontsize=7.5);ax.grid(alpha=.2)
